<section class="panel finance-entry"><div class="section-heading"><div><h2>Gjenerimi vjetor automatik</h2><p>Krijon faturë me tarifë të plotë për 12 muaj. Përpunimi dhe eksportet kryhen në background.</p></div></div><form method="post" action="<?=e(app_url('/admin/finance/generate-annual.php'))?>"><input type="hidden" name="_csrf" value="<?=e($csrf->token())?>"><label class="field">Data e fillimit<input type="date" name="from_date" required value="<?=e(date('Y-m-d'))?>"></label><div class="actions"><button>Gjenero faturat</button><a class="button" href="<?=e(app_url('/admin/finance/invoices.php?year='.$year))?>">Hap faturat</a></div></form></section>
<section class="panel"><h2>Job-et dhe eksportet</h2><p>PDF dhe XLSX krijohen nga worker-i pasi përfundon job-i.</p><div class="table-wrap"><table><thead><tr><th>Job</th><th>Periudha</th><th>Statusi</th><th>Progresi</th><th>Krijuar</th><th>Kaluar</th><th>Gabime</th><th>Totali</th><th>Dokumentet</th></tr></thead><tbody><?php foreach($annualJobs as $job): $percent=(int)$job['total_items']>0?round((int)$job['processed_items']*100/(int)$job['total_items'],1):0;?><tr><td><a href="<?=e(app_url('/admin/finance/invoices.php?job='.(int)$job['id'].'&year='.(int)$job['fiscal_year']))?>">#<?=(int)$job['id']?></a></td><td><?=e($job['period_start'].' – '.$job['period_end'])?></td><td><span class="badge"><?=e($job['status_code'])?></span><br><small><?=e($job['artifact_status']??'PENDING')?></small></td><td><?=number_format($percent,1)?>% (<?=(int)$job['processed_items']?>/<?=(int)$job['total_items']?>)</td><td><?=(int)$job['created_items']?></td><td><?=(int)$job['skipped_items']?></td><td><?=(int)$job['failed_items']?></td><td><?=number_format((float)$job['total_amount'],2)?> EUR</td><td><?php if(($job['artifact_status']??'')==='READY'):?><a class="button" href="<?=e(app_url('/admin/finance/job-artifact.php?job='.(int)$job['id'].'&type=pdf'))?>">PDF</a> <a class="button" href="<?=e(app_url('/admin/finance/job-artifact.php?job='.(int)$job['id'].'&type=xlsx'))?>">XLSX</a><?php elseif(($job['artifact_status']??'')==='FAILED'):?><small><?=e($job['artifact_error']??'Eksporti dështoi')?></small><?php else:?><small>Në përpunim</small><?php endif;?><?php if((int)$job['failed_items']>0):?><form method="post" action="<?=e(app_url('/admin/finance/retry-annual-job.php'))?>"><input type="hidden" name="_csrf" value="<?=e($csrf->token())?>"><input type="hidden" name="job_id" value="<?=(int)$job['id']?>"><button>Riprovo</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if($annualJobs===[]):?><div class="empty">Nuk ka job-e.</div><?php endif;?></div></section>
<section class="panel finance-entry"><h2>Regjistro faturë</h2><form method="get" class="finance-search"><input type="hidden" name="year" value="<?=$year?>"><label class="field">Kërko biznes të pafaturuar<input name="q" maxlength="120" value="<?=e($query)?>" required></label><button>Kërko</button></form><?php if($businesses!==[]):?><form method="post" action="<?=e(app_url('/admin/finance/save-invoice.php'))?>" class="finance-form"><input type="hidden" name="_csrf" value="<?=e($csrf->token())?>"><input type="hidden" name="fiscal_year" value="<?=$year?>"><label class="field">Biznesi<select name="business_id" required><?php foreach($businesses as $business):?><option value="<?=(int)$business['id']?>"><?=e($business['registration_number'].' · '.$business['legal_name'])?></option><?php endforeach;?></select></label><label class="field">Nr. i faturës<input name="invoice_number" maxlength="80" required></label><label class="field">Shuma (EUR)<input name="amount" type="number" min="0.01" step="0.01" required value="<?=e($businesses[0]['estimated_tariff']??'')?>"></label><label class="field">Data<input name="issued_on" type="date" required value="<?=e(date('Y-m-d'))?>"></label><label class="field">Afati<input name="due_on" type="date"></label><label class="field">Shënim<input name="notes" maxlength="500"></label><button>Regjistro</button></form><?php elseif($query!==''):?><div class="empty">Nuk u gjet biznes i pafaturuar.</div><?php endif;?></section>
<section class="panel finance-entry"><h2>Regjistro pagesë</h2><?php if($payableInvoices!==[]):?><form method="post" action="<?=e(app_url('/admin/finance/save-payment.php'))?>" class="finance-form"><input type="hidden" name="_csrf" value="<?=e($csrf->token())?>"><input type="hidden" name="fiscal_year" value="<?=$year?>"><label class="field">Fatura<select name="invoice_id" required><?php foreach($payableInvoices as $invoice):?><option value="<?=(int)$invoice['id']?>"><?=e($invoice['invoice_number'].' · '.$invoice['registration_number'].' · '.$invoice['legal_name'])?></option><?php endforeach;?></select></label><label class="field">Shuma<input name="amount" type="number" min="0.01" step="0.01" required></label><label class="field">Data<input name="paid_on" type="date" required value="<?=e(date('Y-m-d'))?>"></label><label class="field">Referenca<input name="reference" maxlength="100"></label><label class="field">Shënim<input name="notes" maxlength="500"></label><button>Regjistro</button></form><?php else:?><div class="empty">Nuk ka fatura me bilanc.</div><?php endif;?></section>
